    "type:bug": {"group": "type", "color": "d73a4a", "description": "Something is not working as expected", "upstream": true},
    "type:feature": {"group": "type", "color": "a2eeef", "description": "New feature or request", "upstream": true},
    "type:docs": {"group": "type", "color": "0075ca", "description": "Documentation or a question that may improve the docs", "upstream": true},
    "need more information": {"group": "status", "color": "fbca04", "description": "Reporter must add details before a maintainer can act", "upstream": true},
    "status:triage": {"group": "status", "color": "d4c5f9", "description": "Needs a maintainer decision", "upstream": true},
    "triage:possible-duplicate": {"group": "triage", "color": "cfd3d7", "description": "Bot suggestion: may duplicate an earlier issue (maintainer confirms)", "upstream": false},
    "triage:support-question": {"group": "triage", "color": "c5def5", "description": "Bot suggestion: usage/support question, better asked on Discord or Stack Exchange", "upstream": false},
    "triage:possible-spam": {"group": "triage", "color": "000000", "description": "Bot suggestion: spam, scam, phishing, promotion or an untouched template", "upstream": false},
    "triage:security-report": {"group": "triage", "color": "b60205", "description": "Bot suggestion: may describe a vulnerability; see SECURITY.md", "upstream": false}
  },
  "human_only": {
    "triage-agent:halt": {"color": "e11d21", "description": "KILL SWITCH: while any open issue has this label the triage agent does not run or write"},
    "slop": {"description": "Maintainer judgement about low-effort AI content; never applied by the bot"},
    "good first issue": {"description": "Maintainer judgement"},
    "help wanted": {"description": "Maintainer judgement"},
    "status:on-hold": {"description": "Maintainer judgement"}
  },
  "rules": {
    "max_labels_per_issue_run": 3,
    "one_per_group": ["type", "triage"],
    "exclusive": ["triage:possible-spam"],
    "never_add_type_if_present": true
  }
}

{
  "tool": "add_labels",
  "description": "Add labels to an existing GitHub issue or pull request for categorization and filtering. Labels must already exist in the repository. For creating new issues with labels, use create_issue with the labels property instead. CONSTRAINTS: Maximum 1 add_labels call(s) allowed. Maximum 3 label(s) per call. Only these labels are allowed: [\"type:bug\" \"type:feature\" \"type:docs\" \"need more information\" \"status:triage\" \"triage:possible-duplicate\" \"triage:support-question\" \"triage:possible-spam\" \"triage:security-report\"]. Target: 35911. INTENT ENCOURAGED: Include rationale (string, max 280 chars) and confidence (exactly one of: LOW, MEDIUM, HIGH) with each call. These fields are optional but strongly encouraged — they improve transparency and should normally be included. Use suggest: true alongside rationale and confidence to route for human review.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "integrity": {
        "description": "Trustworthiness level of the message source (e.g., \"low\", \"medium\", \"high\").",
        "type": "string"
      },
      "item_number": {
        "description": "Issue or PR number to add labels to. This is the numeric ID from the GitHub URL (e.g., 456 in github.com/owner/repo/issues/456). Can also be a temporary_id from a previously created issue in the same workflow run — use the '#aw_abc123' form; the bare 'aw_abc123' form is also accepted and normalised to '#aw_abc123'. If omitted, adds labels to the issue or PR that triggered this workflow. Only works for issue or pull_request event triggers. For schedule, workflow_dispatch, or other triggers, item_number is required — omitting it will silently skip the label operation.",
        "pattern": "^(\\d+|#?aw_[A-Za-z0-9_]{3,12})$",
        "type": [
          "number",
          "string"
        ]
      },
      "labels": {
        "description": "Labels to add. Prefer structured label objects: {\"name\": \"bug\", \"rationale\": \"The report describes reproducible incorrect behavior.\", \"confidence\": \"HIGH\", \"suggest\": true}. Plain strings are also accepted for compatibility. Include rationale (string, max 280 chars) and confidence (LOW, MEDIUM, or HIGH) to improve transparency; use suggest: true to route for human review. Labels must exist in the repository.",
        "items": {
          "oneOf": [
            {
              "type": "string"
            },
            {
              "additionalProperties": false,
              "properties": {
                "confidence": {
                  "description": "Optional confidence level for the change.",
                  "enum": [
                    "LOW",
                    "MEDIUM",
                    "HIGH"
                  ],
                  "type": "string"
                },
                "name": {
                  "description": "Label name to apply.",
                  "type": "string"
                },
                "rationale": {
                  "description": "Optional rationale for the change (max 280 characters).",
                  "maxLength": 280,
                  "type": "string"
                },
                "suggest": {
                  "description": "When true, route the change through pending human review instead of applying it immediately.",
                  "type": "boolean"
                }
              },
              "required": [
                "name"
              ],
              "type": "object"
            }
          ]
        },
        "minItems": 1,
        "type": "array"
      },
      "secrecy": {
        "description": "Confidentiality level of the message content (e.g., \"public\", \"internal\", \"private\").",
        "type": "string"
      }
    },
    "required": [
      "labels"
    ],
    "additionalProperties": false
  }
}
